# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">"VATAN" ŞİİRİ ÇÖZÜMLEMESİ VE ŞİİR – DÜZYAZI KARŞILAŞTIRMASI</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Nurettin Özdemir — "Vatan" Şiiri</text>\n  <text x="50" y="106" font-size="11.5" fill="#334155">• Antalya\'da mavi su • Gümüşhane\'de yemyeşil bahçe</text>\n  <text x="50" y="128" font-size="11.5" fill="#334155">• Zonguldak\'ta maden işçisi • Rize\'de çay toplayan gelin</text>\n  <text x="50" y="150" font-size="11.5" fill="#334155">• Ceylânpınar\'da ince ceylan • Edirne\'de ince minare</text>\n  <text x="50" y="172" font-size="11.5" fill="#334155">• Isparta halısında gül • Kütahya çinisinde ateşten lale</text>\n  <text x="50" y="194" font-size="11.5" fill="#334155">• Anıtkabir\'de sonsuza dek sönmeyecek meşale!</text>\n  <text x="187" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Ana Duygu: Derin vatan sevgisi ve millî birlik</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Şiir ile Düzyazı Arasındaki Farklar</text>\n  <text x="375" y="108" font-size="11.5" font-weight="bold" fill="#166534">Şiir (Manzum Metin):</text>\n  <text x="375" y="126" font-size="11" fill="#334155">• Dizelerden (mısra) ve dörtlük/bölümlerden oluşur.</text>\n  <text x="375" y="144" font-size="11" fill="#334155">• Şairi vardır; \'ana duygu\' (tema) ve ses uyumu öne çıkar.</text>\n  <text x="375" y="170" font-size="11.5" font-weight="bold" fill="#15803d">Düzyazı (Mensur Metin):</text>\n  <text x="375" y="188" font-size="11" fill="#334155">• Cümlelerden ve paragraflardan oluşur.</text>\n  <text x="375" y="206" font-size="11" fill="#334155">• Yazarı vardır; \'ana fikir\' ve düşünceyi geliştirme vardır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZ SANATLARI VE GEÇİŞ-BAĞLANTI İFADELERİ</text>\n  <rect x="35" y="55" width="320" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="195" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Söz Sanatları (Edebî Sanatlar)</text>\n  <text x="50" y="106" font-size="11" fill="#334155">• Benzetme (Teşbih): "Vatan... sönmeyecek bir meşaledir."</text>\n  <text x="50" y="128" font-size="11" fill="#334155">• Kişileştirme (Teşhis): "Dağların, bulutların gözyaşı"</text>\n  <text x="50" y="150" font-size="11" fill="#334155">• Konuşturma (İntak): Bayrağın "Korkmayın!" diye fısıldaması</text>\n  <text x="50" y="172" font-size="11" fill="#334155">• Abartma (Mübalağa): "Dağları tutuşturacak bir ateş oldum."</text>\n  <text x="50" y="194" font-size="11" fill="#334155">• Karşıtlık (Tezat): Islanmak – kavrulmak / ağlamak – gülmek</text>\n  <rect x="370" y="55" width="295" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Geçiş ve Bağlantı İfadeleri</text>\n  <text x="385" y="108" font-size="11.5" fill="#334155">• Düşünceyi Değiştirenler:</text>\n  <text x="395" y="126" font-size="11" font-weight="bold" fill="#1e40af">ama, fakat, lakin, yalnız, ancak, oysa, buna rağmen</text>\n  <text x="385" y="152" font-size="11.5" fill="#334155">• Neden-Sonuç ve Destekleyenler:</text>\n  <text x="395" y="170" font-size="11" font-weight="bold" fill="#1e40af">çünkü, bu nedenle, böylece, üstelik, ayrıca</text>\n  <text x="385" y="198" font-size="11" fill="#475569">"Gezmek istiyordum yalnız karar veremiyorum."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAPIM-ÇEKİM EKLERİ, TAMLAMALAR VE -DA / -DE YAZIMI</text>\n  <rect x="25" y="55" width="210" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="130" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kök, Yapım ve Çekim Eki</text>\n  <text x="40" y="108" font-size="11" fill="#334155">• Yapım Eki: Yeni kelime türetir.</text>\n  <text x="45" y="126" font-size="11" font-weight="bold" fill="#166534">düş → düşün- → düşünce → düşünceli</text>\n  <text x="45" y="144" font-size="11" font-weight="bold" fill="#166534">duy- → duygu • kitap → kitapçı</text>\n  <text x="40" y="170" font-size="11" fill="#334155">• Çekim Eki: Anlamı değiştirmez,</text>\n  <text x="45" y="188" font-size="11" fill="#475569">hâl, çoğul, iyelik, zaman bildirir (ol-du).</text>\n  <rect x="250" y="55" width="205" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="352" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İsim ve Sıfat Tamlamaları</text>\n  <text x="265" y="108" font-size="11" fill="#334155">• Sıfat Tamlaması (Nasıl/Hangi?):</text>\n  <text x="270" y="126" font-size="11" font-weight="bold" fill="#1e40af">mavi su, yemyeşil bahçe, çorak tarla,</text>\n  <text x="270" y="144" font-size="11" font-weight="bold" fill="#1e40af">kutsal düşünce, köpüklü yele</text>\n  <text x="265" y="170" font-size="11" fill="#334155">• İsim Tamlaması (Ne / Neyin?):</text>\n  <text x="270" y="188" font-size="11" font-weight="bold" fill="#1e40af">kardeş mezarı, Isparta halısı (Belirtisiz)</text>\n  <text x="270" y="206" font-size="11" font-weight="bold" fill="#1e40af">dağların gözyaşı (Belirtili)</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Bulunma Eki ve Bağlaç da/de</text>\n  <text x="485" y="108" font-size="11" fill="#334155">• Bulunma Hâl Eki (-da/-de/-ta/-te):</text>\n  <text x="490" y="126" font-size="11" font-weight="bold" fill="#9d174d">Bitişik yazılır, nerede sorusunu yanıtlar:</text>\n  <text x="490" y="144" font-size="11" fill="#334155">"Antalya\'da, Posof\'ta, Anıtkabir\'de"</text>\n  <text x="485" y="170" font-size="11" fill="#334155">• Bağlaç olan da / de:</text>\n  <text x="490" y="188" font-size="11" font-weight="bold" fill="#9d174d">Ayrı yazılır (-ta/-te şekli yoktur):</text>\n  <text x="490" y="206" font-size="11" fill="#334155">"Yanıp da sonsuza dek sönmeyecek"</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
